for _ in range(int(input())):
    X, Y, Z = map(int, input().split())
    B = []
    for _ in range(Y):
        B.append(list(map(int, input().split())))
    A = defaultdict(int)
    for i in range(X):
        for j in range(Y):
            prefix_sum = 0
            for k in range(Z):
                prefix_sum += B[j][k]
                A[(i, j, k)] = prefix_sum
