def bfs(graph, start, end, path, visited):
    queue = deque([(start, path)])
    while queue:
        vertex, path = queue.popleft()
        if vertex == end:
            return path
        for neighbor in graph[vertex]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + str(neighbor)))

